///  Catalog Cross-Match - exactly one arm is set.
class XMT {
  XMT._(this._bc, this._bcOffset);
  factory XMT(List<int> bytes) {
    final rootRef = fb.BufferContext.fromBytes(bytes);
    return reader.read(rootRef, 0);
  }

  static const fb.Reader<XMT> reader = _XMTReader();

  final fb.BufferContext _bc;
  final int _bcOffset;

  XMTMatchRequest? get MATCH_REQUEST => XMTMatchRequest.reader.vTableGetNullable(_bc, _bcOffset, 4);
  XMTMatchRequest? get matchRequest => MATCH_REQUEST;
  XMTMatchReport? get MATCH_REPORT => XMTMatchReport.reader.vTableGetNullable(_bc, _bcOffset, 6);
  XMTMatchReport? get matchReport => MATCH_REPORT;
  XMTComposeRecipe? get COMPOSE_RECIPE => XMTComposeRecipe.reader.vTableGetNullable(_bc, _bcOffset, 8);
  XMTComposeRecipe? get composeRecipe => COMPOSE_RECIPE;
  XMTComposeReport? get COMPOSE_REPORT => XMTComposeReport.reader.vTableGetNullable(_bc, _bcOffset, 10);
  XMTComposeReport? get composeReport => COMPOSE_REPORT;
  XMTIntegrateRecipe? get INTEGRATE_RECIPE => XMTIntegrateRecipe.reader.vTableGetNullable(_bc, _bcOffset, 12);
  XMTIntegrateRecipe? get integrateRecipe => INTEGRATE_RECIPE;
  XMTIntegrateReport? get INTEGRATE_REPORT => XMTIntegrateReport.reader.vTableGetNullable(_bc, _bcOffset, 14);
  XMTIntegrateReport? get integrateReport => INTEGRATE_REPORT;
  XMTEpochFitPolicy? get EPOCH_FIT_POLICY => XMTEpochFitPolicy.reader.vTableGetNullable(_bc, _bcOffset, 16);
  XMTEpochFitPolicy? get epochFitPolicy => EPOCH_FIT_POLICY;
  XMTEpochFitReport? get EPOCH_FIT_REPORT => XMTEpochFitReport.reader.vTableGetNullable(_bc, _bcOffset, 18);
  XMTEpochFitReport? get epochFitReport => EPOCH_FIT_REPORT;

  @override
  String toString() {
    return 'XMT{matchRequest: ${matchRequest}, matchReport: ${matchReport}, composeRecipe: ${composeRecipe}, composeReport: ${composeReport}, integrateRecipe: ${integrateRecipe}, integrateReport: ${integrateReport}, epochFitPolicy: ${epochFitPolicy}, epochFitReport: ${epochFitReport}}';
  }
}

class _XMTReader extends fb.TableReader<XMT> {
  const _XMTReader();

  @override
  XMT createObject(fb.BufferContext bc, int offset) =>
    XMT._(bc, offset);
}

